// Published service worker — caches the Blazor WASM app for offline use
const CACHE_NAME = 'cashflow202-v1';

// This file is generated by the Blazor publish output and defines `self.assetsManifest`.
self.importScripts('./service-worker-assets.js');
self.addEventListener('install', event => {
    event.waitUntil(
        (async () => {
            const cache = await caches.open(CACHE_NAME);
            // The service-worker-assets.js manifest is generated by the Blazor build
            // and lists all files to pre-cache for offline use.
            if (typeof self.assetsManifest !== 'undefined') {
                const assetsToCache = self.assetsManifest.assets.map(a => a.url);
                await cache.addAll(assetsToCache);
            }
        })()
    );
    self.skipWaiting();
});

self.addEventListener('activate', event => {
    event.waitUntil(
        (async () => {
            const keys = await caches.keys();
            await Promise.all(keys.filter(k => k !== CACHE_NAME).map(k => caches.delete(k)));
        })()
    );
    clients.claim();
});

self.addEventListener('fetch', event => {
    if (event.request.method !== 'GET') return;
    event.respondWith(
        (async () => {
            const cached = await caches.match(event.request);
            if (cached) return cached;
            try {
                const response = await fetch(event.request);
                if (response.ok && response.type === 'basic') {
                    const cache = await caches.open(CACHE_NAME);
                    cache.put(event.request, response.clone());
                }
                return response;
            } catch {
                const fallback = await caches.match('/index.html');
                return fallback ?? new Response('Offline', { status: 503 });
            }
        })()
    );
});
